final class AVADirPartyQuickCreateFormFrm_DirPartyTable_DirPersonDS_Extension
{
    [DataField]
    class PersonalTitle
    {
        /// <summary>
        ///    AVA <c>lookupReference</c> method.
        /// </summary>
